"""Generate explicit model phonemes with eSpeak NG 1.50 and ffmpeg, never letter names.
ESPEAK_NG may name a custom executable. Run from repository root.
"""
import os,json,pathlib,subprocess,hashlib,tempfile
rows=[('umlaut-a','ä · 1','E','de'),('umlaut-a','ä · 2','E:','de'),('umlaut-o','ö · 1','W','de'),('umlaut-o','ö · 2','Y:','de'),('umlaut-u','ü · 1','y','de'),('umlaut-u','ü · 2','y:','de'),('eszett','ß','s:','de'),('ich','ch · ich','C:','de'),('ach','ch · ach','x:','de'),('sch','sch','S:','de'),('sch','st','St','de'),('sch','sp','Sp','de'),('ei-ie','ei','aI','de'),('ei-ie','ie','i:','de'),('eu','eu · äu','OY','de'),('z','z','ts','de'),('v-w','v · Vater','f:','de'),('v-w','w','v:','en'),('r','r','r','de'),('r','-er','3','de')]
exe=os.environ.get('ESPEAK_NG','espeak-ng');entries=[]
with tempfile.TemporaryDirectory() as tmp:
 for n,(section,label,phonemes,voice) in enumerate(rows):
  text='[['+phonemes+']]';wav=f'{tmp}/{n}.wav';mp3=f'{tmp}/{n}.mp3'
  ipa=subprocess.check_output([exe,'-v',voice,'--ipa','-q',text],text=True).strip()
  assert ipa, (label,'empty phoneme transcription')
  subprocess.run([exe,'-v',voice,'-s','110','-a','120','-w',wav,text],check=True)
  subprocess.run(['ffmpeg','-v','error','-y','-i',wav,'-af','silenceremove=start_periods=1:start_duration=0.01:start_threshold=-50dB,areverse,silenceremove=start_periods=1:start_duration=0.01:start_threshold=-50dB,areverse,apad=pad_dur=0.12,asetpts=N/SR/TB','-codec:a','libmp3lame','-q:a','2',mp3],check=True)
  raw=pathlib.Path(mp3).read_bytes();sha=hashlib.sha256(raw).hexdigest();url=f'/clips/{sha}.mp3';pathlib.Path('public'+url).write_bytes(raw)
  entries.append(dict(id=f'heading198-{n+1:02}',section=section,label=label,phonemes=phonemes,voice=voice,engineIPA=ipa,url=url,sha256=sha,bytes=len(raw)))
pathlib.Path('data/heading-sounds198.json').write_text(json.dumps(dict(engine='eSpeak NG 1.50',source='https://github.com/espeak-ng/espeak-ng/tree/1.50',notes='Explicit phoneme input, simplified formant models. Not native recordings or letter names. German r is the valid tongue-tip variant. German 3 models vocalized -er. English voice is used only for isolated voiced v to avoid German final devoicing. No engine code or voice database is distributed.',entries=entries),ensure_ascii=False,indent=2)+'\n')
pathlib.Path('src/lib/heading-sounds.ts').write_text('// Generated by scripts/build-heading-sounds198.py. Explicit phoneme clips, not spelled letter names.\nexport const headingSounds:ReadonlyArray<{id:string;section:string;label:string;url:string}>='+json.dumps([{k:r[k] for k in ['id','section','label','url']} for r in entries],ensure_ascii=False,indent=2)+';\n')
print('Generated',len(entries),'model clips');print([(e['label'],e['engineIPA']) for e in entries])
